import os
from google.cloud import vision_v1

def extract_receipt_data(image_path):
    client = vision_v1.ImageAnnotatorClient()
    with open(image_path, 'rb') as image_file:
        content = image_file.read()
    image = vision_v1.Image(content=content)

    response = client.document_text_detection(image=image)
    document = response.full_text_annotation

    merchant = None
    tax = None
    total = None
    items = []

    for page in document.pages:
        for block in page.blocks:
            block_text = ''
            for paragraph in block.paragraphs:
                for word in paragraph.words:
                    word_text = ''.join(symbol.text for symbol in word.symbols)
                    block_text += word_text + ' '
            block_text = block_text.strip()

            if 'merchant' in block_text.lower():
                merchant = ' '.join(block_text.split()[1:])
            elif 'tax' in block_text.lower():
                tax = ' '.join(block_text.split()[1:])
            elif 'total' in block_text.lower():
                total = ' '.join(block_text.split()[1:])
            else:
                items.append(block_text)

    return {
        'merchant': merchant,
        'tax': tax,
        'total': total,
        'items': items
    }

if __name__ == '__main__':
    image_path = os.environ['RECEIPT_IMAGE_PATH']
    receipt_data = extract_receipt_data(image_path)
    print(receipt_data)
